            float origSat = min(1.0,length(yuv.yz)*2.5); 
            float2 satUV = yuv.yz * amzp_vib;

            yuv.yz = mix(satUV,yuv.yz,origSat);

            yuv.yz = yuv.yz * (amzp_saturation+1.0);

            rgb = yuv * yuv2rgb;
            rgb = rgb + float3(amzp_offset)*a;
            rgb = pow(rgb,float3(1.0/amzp_gamma));
            rgb = rgb * pow(2.0,amzp_exposure);
            rgb = mix(rgb, rgb * colorTemperatureToRGB(amzp_temperature * 1000.0), 0.8);


            exsat = float4(rgb,a);

                float4 bright;
                float3 rgbx = exsat.rgb;
                float ax = exsat.a;
                float3 yuvbc = rgbx * rgb2yuv;

